export interface ConnectorConfig {
  /** Shopify app client secret for HMAC verification */
  shopifyClientSecret: string;
  /** Airtable API key (Bearer token) */
  airtableApiKey: string;
  /** Airtable base ID (e.g., appXXXXXXXXXXXXXX) */
  airtableBaseId: string;
  /** Airtable table name or ID */
  airtableTableNameOrId: string;
  /** Raw request body from the incoming Shopify webhook (for HMAC verification) */
  rawBody: string;
  /** Value of the X-Shopify-Hmac-SHA256 header from the incoming webhook */
  hmacHeader: string;
  /** Injected fetch implementation (for testing) */
  fetch?: typeof fetch;
}

export interface ShopifyOrderPaidPayload {
  ucp: {
    version: string;
    capabilities: Record<string, Array<{ version: string }>>;
  };
  id: string;
  label: string;
  currency: string;
  totals: Array<{
    type: string;
    display_text: string;
    amount: number;
  }>;
  line_items: Array<{
    id: string;
    item: {
      id: string;
      title: string;
      price: number;
      image_url: string;
    };
    quantity: {
      original: number;
      total: number;
      fulfilled: number;
    };
    totals: Array<{ type: string; display_text: string; amount: number }>;
    status: string;
    parent_id: string | null;
  }>;
  fulfillment: {
    expectations: Array<{
      id: string;
      line_items: Array<{ id: string; quantity: number }>;
      method_type: string;
      destination: {
        first_name: string;
        last_name: string;
        street_address: string;
        address_locality: string;
        address_region: string;
        address_country: string;
        postal_code: string;
      };
    }>;
    events: Array<{
      id: string;
      occurred_at: string;
      type: string;
      tracking_number: string;
      tracking_url: string;
      carrier: string;
      line_items: Array<{ id: string; quantity: number }>;
    }>;
    adjustments: Array<{
      id: string;
      type: string;
      occurred_at: string;
      status: string;
      totals: Array<{ type: string; amount: number }>;
      line_items: Array<{ id: string; quantity: number }>;
    }>;
  };
}

export interface HandleResult {
  airtableRecordId: string;
  created: boolean;
  updated: boolean;
}

async function verifyShopifyHmac(
  fetch: typeof fetch,
  rawBody: string,
  hmacHeader: string,
): Promise<void> {
  const response = await fetch('/webhooks', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Hmac-SHA256': hmacHeader,
    },
    body: rawBody,
  });

  if (!response.ok) {
    throw new Error(`Shopify HMAC verification failed: ${response.status} ${response.statusText} at POST /webhooks`);
  }

  const result = await response.json() as { valid: boolean };
  if (!result.valid) {
    throw new Error('Shopify HMAC verification returned invalid');
  }
}

async function upsertAirtableRecord(
  fetch: typeof fetch,
  config: ConnectorConfig,
  fields: Record<string, unknown>,
): Promise<{ id: string; created: boolean; updated: boolean }> {
  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableNameOrId}`;
  const body = {
    performUpsert: {
      fieldsToMergeOn: ['Order Number'],
    },
    records: [{ fields }],
  };

  const response = await fetch(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${config.airtableApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    throw new Error(`Airtable upsert failed: ${response.status} ${response.statusText} at PATCH ${url}`);
  }

  const result = await response.json() as {
    records: Array<{ id: string; fields: Record<string, unknown> }>;
    updatedRecords: string[][];
    createdRecords: string[];
  };

  const record = result.records[0];
  if (!record?.id) {
    throw new Error('Airtable upsert returned no record ID');
  }

  const created = result.createdRecords.includes(record.id);
  const updated = result.updatedRecords.some((arr) => arr.includes(record.id));

  return { id: record.id, created, updated };
}

export async function handle(payload: ShopifyOrderPaidPayload, config: ConnectorConfig): Promise<HandleResult> {
  const fetch = config.fetch ?? globalThis.fetch;

  // Validate required fields
  if (!payload.id) {
    throw new Error('Missing required field: order id (payload.id)');
  }
  if (!payload.label) {
    throw new Error('Missing required field: order label (payload.label)');
  }
  const totalEntry = payload.totals.find((t) => t.type === 'total');
  if (totalEntry === undefined || totalEntry.amount === undefined) {
    throw new Error('Missing required field: total price (payload.totals[].amount where type=total)');
  }
  if (!payload.fulfillment?.events?.length || !payload.fulfillment.events[0].occurred_at) {
    throw new Error('Missing required field: created_at (payload.fulfillment.events[0].occurred_at)');
  }

  // Verify HMAC with Shopify
  await verifyShopifyHmac(fetch, config.rawBody, config.hmacHeader);

  // Extract and map fields
  const totalPrice = totalEntry.amount / 100; // cents to dollars
  const createdAt = payload.fulfillment.events[0].occurred_at;
  // Customer email not present in documented example; default to empty string
  const customerEmail = '';

  const fields = {
    'Order Number': payload.label,
    'Customer Email': customerEmail,
    'Total Price': totalPrice,
    'Created At': createdAt,
  };

  const { id, created, updated } = await upsertAirtableRecord(fetch, config, fields);

  return { airtableRecordId: id, created, updated };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, ShopifyOrderPaidPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const rawBody = JSON.stringify(SOURCE_EXAMPLE);
    const result = await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderPaidPayload, {
      shopifyClientSecret: 'test-secret',
      airtableApiKey: 'test-key',
      airtableBaseId: 'appTestBase',
      airtableTableNameOrId: 'tblTestTable',
      rawBody,
      hmacHeader: 'dummy-hmac',
      fetch,
    });
    expect(calls.length).toBeGreaterThan(0);
    expect(result.airtableRecordId).toBe('recABC123');
    expect(result.updated).toBe(true);
    expect(result.created).toBe(false);
  });
});

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    shopifyClientSecret: 'test-secret',
    airtableApiKey: 'test-key',
    airtableBaseId: 'appTestBase',
    airtableTableNameOrId: 'tblTestTable',
    rawBody: JSON.stringify(SOURCE_EXAMPLE),
    hmacHeader: 'test-hmac',
  };

  const validPayload = SOURCE_EXAMPLE as unknown as ShopifyOrderPaidPayload;

  it('happy path: verifies HMAC then upserts to Airtable with correct field mapping', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === '/webhooks' && req.method === 'POST') {
        return jsonResponse({ valid: true });
      }
      if (req.url.includes('api.airtable.com') && req.method === 'PATCH') {
        return jsonResponse(
          {
            records: [{ id: 'recNEW123', fields: req.json?.records?.[0]?.fields }],
            updatedRecords: [],
            createdRecords: ['recNEW123'],
          },
          200,
        );
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(validPayload, { ...baseConfig, fetch });

    expect(result.airtableRecordId).toBe('recNEW123');
    expect(result.created).toBe(true);
    expect(result.updated).toBe(false);

    // Verify HMAC call
    const hmacCall = calls.find((c) => c.url === '/webhooks' && c.method === 'POST');
    expect(hmacCall).toBeDefined();
    expect(hmacCall?.headers.get('x-shopify-hmac-sha256')).toBe('test-hmac');
    expect(hmacCall?.body).toBe(baseConfig.rawBody);

    // Verify Airtable upsert call
    const airtableCall = calls.find((c) => c.url.includes('api.airtable.com') && c.method === 'PATCH');
    expect(airtableCall).toBeDefined();
    expect(airtableCall?.headers.get('authorization')).toBe('Bearer test-key');
    expect(airtableCall?.json).toMatchObject({
      performUpsert: { fieldsToMergeOn: ['Order Number'] },
      records: [
        {
          fields: {
            'Order Number': '#1042',
            'Customer Email': '',
            'Total Price': 79.77,
            'Created At': '2026-03-25T14:30:00-04:00',
          },
        },
      ],
    });
  });

  it('auth mechanism: sends Shopify HMAC header and Airtable Bearer token', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === '/webhooks') return jsonResponse({ valid: true });
      if (req.url.includes('api.airtable.com')) return jsonResponse({ records: [{ id: 'rec1' }], updatedRecords: [['rec1']], createdRecords: [] });
      return jsonResponse({}, 404);
    });

    await handle(validPayload, { ...baseConfig, fetch });

    const hmacCall = calls.find((c) => c.url === '/webhooks');
    expect(hmacCall?.headers.get('x-shopify-hmac-sha256')).toBe('test-hmac');

    const airtableCall = calls.find((c) => c.url.includes('api.airtable.com'));
    expect(airtableCall?.headers.get('authorization')).toBe('Bearer test-key');
  });

  it('field mapping: maps label to Order Number, total cents to dollars, first event to Created At', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === '/webhooks') return jsonResponse({ valid: true });
      if (req.url.includes('api.airtable.com')) {
        const fields = req.json?.records?.[0]?.fields;
        expect(fields).toMatchObject({
          'Order Number': '#1042',
          'Total Price': 79.77,
          'Created At': '2026-03-25T14:30:00-04:00',
        });
        return jsonResponse({ records: [{ id: 'rec1', fields }], updatedRecords: [['rec1']], createdRecords: [] });
      }
      return jsonResponse({}, 404);
    });

    await handle(validPayload, { ...baseConfig, fetch });
  });

  it('missing required field: throws descriptive error for missing order id', async () => {
    const payload = { ...validPayload, id: '' } as ShopifyOrderPaidPayload;
    const { fetch } = fakeFetch(() => jsonResponse({ valid: true }));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: order id');
  });

  it('missing required field: throws descriptive error for missing label', async () => {
    const payload = { ...validPayload, label: '' } as ShopifyOrderPaidPayload;
    const { fetch } = fakeFetch(() => jsonResponse({ valid: true }));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: order label');
  });

  it('missing required field: throws descriptive error for missing total price', async () => {
    const payload = { ...validPayload, totals: [] } as ShopifyOrderPaidPayload;
    const { fetch } = fakeFetch(() => jsonResponse({ valid: true }));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: total price');
  });

  it('missing required field: throws descriptive error for missing created_at', async () => {
    const payload = { ...validPayload, fulfillment: { ...validPayload.fulfillment, events: [] } } as ShopifyOrderPaidPayload;
    const { fetch } = fakeFetch(() => jsonResponse({ valid: true }));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: created_at');
  });

  it('non-2xx from Shopify HMAC verification throws with status and endpoint', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401));
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('Shopify HMAC verification failed: 401 Unauthorized at POST /webhooks');
  });

  it('non-2xx from Airtable upsert throws with status and endpoint', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url === '/webhooks') return jsonResponse({ valid: true });
      return jsonResponse({ error: 'not found' }, 404);
    });
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('Airtable upsert failed: 404 Not Found at PATCH');
  });

  it('HMAC verification returns invalid throws error', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ valid: false }, 200));
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('Shopify HMAC verification returned invalid');
  });
});

# Shopify Order Paid → Airtable Upsert Connector

## What it does

This connector processes a Shopify `orders/paid` webhook payload, verifies its authenticity using HMAC-SHA256, and upserts a record into Airtable keyed on **Order Number**.

**Flow:**
1. Receive parsed Shopify webhook payload (UCP envelope).
2. Validate required fields: order id, label, total price, created timestamp.
3. Verify HMAC by calling Shopify's `/webhooks` endpoint with the raw request body and `X-Shopify-Hmac-SHA256` header.
4. On successful verification, upsert a record to Airtable using `performUpsert` with `fieldsToMergeOn: ["Order Number"]`.

## Configuration / Environment Variables

| Config Property | Environment Variable | Description |
|-----------------|----------------------|-------------|
| `shopifyClientSecret` | `SHOPIFY_CLIENT_SECRET` | Shopify app client secret used for HMAC verification (passed to verification call). |
| `airtableApiKey` | `AIRTABLE_API_KEY` | Airtable personal access token (Bearer). |
| `airtableBaseId` | `AIRTABLE_BASE_ID` | Airtable base ID (e.g., `appXXXXXXXXXXXXXX`). |
| `airtableTableNameOrId` | `AIRTABLE_TABLE_NAME` | Airtable table name or ID. |
| `rawBody` | — | Raw request body string from the incoming webhook (for HMAC verification). |
| `hmacHeader` | — | Value of the `X-Shopify-Hmac-SHA256` header from the incoming webhook. |
| `fetch` | — | Injected `fetch` implementation (for testing). |

**Note:** `rawBody` and `hmacHeader` are runtime values from the HTTP request that delivers the webhook; they are not static secrets.

## Usage Example

```typescript
import { handle, ConnectorConfig } from './connector';

// In your webhook handler (e.g., Node/Express, Cloudflare Workers, etc.):
app.post('/webhooks', async (req, res) => {
  const rawBody = JSON.stringify(req.body); // preserve exact bytes for HMAC
  const hmacHeader = req.headers['x-shopify-hmac-sha256'];

  const config: ConnectorConfig = {
    shopifyClientSecret: process.env.SHOPIFY_CLIENT_SECRET!,
    airtableApiKey: process.env.AIRTABLE_API_KEY!,
    airtableBaseId: process.env.AIRTABLE_BASE_ID!,
    airtableTableNameOrId: process.env.AIRTABLE_TABLE_NAME!,
    rawBody,
    hmacHeader,
  };

  try {
    const result = await handle(req.body, config);
    res.json({ success: true, ...result });
  } catch (err) {
    console.error(err);
    res.status(500).json({ success: false, error: err.message });
  }
});
```

## Assumptions

- The Airtable table already has a field named **Order Number** configured as a primary/unique field.
- The webhook payload includes an `order` object with `id`, `customer`, `total_price`, and `created_at` fields (per plan). The documented example uses `label` for order number, `totals[].amount` (cents) for total price, and `fulfillment.events[0].occurred_at` for created timestamp.
- **Customer Email** is not present in the documented Shopify payload; the connector defaults it to an empty string.
- Deduplication by order id + HMAC is handled externally (e.g., via a persistent store) before this connector runs.
- Shopify HMAC verification uses the shared secret and the raw request body with the `X-Shopify-Hmac-SHA256` header.
- The connector must respond 2xx quickly; Shopify retries up to 8 times over 4 hours.
- Airtable upsert uses PATCH with `performUpsert.fieldsToMergeOn`; composite key requires exact match on all listed fields.

