    expect(result.created).toBe(true);
    expect(result.updated).toBe(false);

    // Verify Airtable upsert call
    const airtableCall = calls.find((c) => c.url.includes('api.airtable.com') && c.method === 'PATCH');
    expect(airtableCall).toBeDefined();
    expect(airtableCall?.headers.get('authorization')).toBe('Bearer test-key');
    expect(airtableCall?.json).toMatchObject({
      performUpsert: { fieldsToMergeOn: ['Order Number'] },
      records: [
        {
          fields: {
            'Order Number': '#1042',
            'Customer Email': '',
            'Total Price': 79.77,
            'Created At': '2026-03-25T14:30:00-04:00',
          },
        },
      ],
    });
  });

  it('auth mechanism: sends Airtable Bearer token', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('api.airtable.com')) return jsonResponse({ records: [{ id: 'rec1' }], updatedRecords: [['rec1']], createdRecords: [] });
      return jsonResponse({}, 404);
    });

    await handle(validPayload, { ...baseConfig, fetch });

    const airtableCall = calls.find((c) => c.url.includes('api.airtable.com'));
    expect(airtableCall?.headers.get('authorization')).toBe('Bearer test-key');
  });

  it('field mapping: maps label to Order Number, total cents to dollars, first event to Created At', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('api.airtable.com')) {
        const fields = (req.json as any)?.records?.[0]?.fields;
        expect(fields).toMatchObject({
          'Order Number': '#1042',
          'Total Price': 79.77,
          'Created At': '2026-03-25T14:30:00-04:00',
        });
        return jsonResponse({ records: [{ id: 'rec1', fields }], updatedRecords: [['rec1']], createdRecords: [] });
      }
      return jsonResponse({}, 404);
    });

    await handle(validPayload, { ...baseConfig, fetch });
  });

  it('missing required field: throws descriptive error for missing order id', async () => {
    const payload = { ...validPayload, id: '' } as ShopifyOrderPaidPayload;
    const { fetch } = fakeFetch(() => jsonResponse({ valid: true }));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: order id');
  });

  it('missing required field: throws descriptive error for missing label', async () => {
    const payload = { ...validPayload, label: '' } as ShopifyOrderPaidPayload;
    const { fetch } = fakeFetch(() => jsonResponse({ valid: true }));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: order label');
  });

  it('missing required field: throws descriptive error for missing total price', async () => {
    const payload = { ...validPayload, totals: [] } as ShopifyOrderPaidPayload;
    const { fetch } = fakeFetch(() => jsonResponse({ valid: true }));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: total price');
  });

  it('non-2xx target response: throws error with status and endpoint', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('Airtable upsert failed: 401 Unauthorized at PATCH');
  });

  it('invalid HMAC: throws descriptive error', async () => {
    const config = { ...baseConfig, hmacHeader: 'invalid-hmac' };
    const { fetch } = fakeFetch(() => jsonResponse({ valid: true }));
    await expect(handle(validPayload, config)).rejects.toThrow('Invalid HMAC signature');
